package az.youtube.dto.request;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

import java.util.UUID;

/**
 * @param eventId        generated by the player once per view and repeated on retries
 * @param watchedSeconds how long this view has been watched so far
 */
public record ViewRequest(@NotNull UUID eventId, @PositiveOrZero @Max(86_400) int watchedSeconds) {
}
